def assign_customers_to_routes(instance, routes):
    unassigned_customers = list(instance.customer_ids)

    while unassigned_customers:
        best_route = None
        best_distance_increase = float('inf')
        best_customer = None

        for route in routes:
            for customer in unassigned_customers:
                new_route = route[:-1] + [customer, instance.depot_id]
                new_states = propagate_route(instance, new_route)

                if all(state.battery_arrival >= 0 for state in new_states):
